'use strict';
(()=>{
 let context,output,analyser,gain,filter,source,buffer,loading=false,retryAt=0,settings={},isScreen=false,testUntil=0,lastStatus='',lastFx=0;
 function report(status,detail){if(lastStatus===status+detail)return;lastStatus=status+detail;window.dispatchEvent(new CustomEvent('race-audio-state',{detail:{status,detail,voice:'race'}}))}
 function unlock(provided){try{if(context?.state==='closed'){context=null;output=null;source=null}context??=(provided?.state!=='closed'?provided:null)||new(window.AudioContext||window.webkitAudioContext)();if(!output){output=context.createDynamicsCompressor();output.threshold.value=-8;output.ratio.value=3;analyser=context.createAnalyser();analyser.fftSize=512;output.connect(analyser);analyser.connect(context.destination);gain=context.createGain();gain.gain.value=0;gain.connect(output);filter=context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=2000;filter.connect(gain)}if(context.state==='suspended'||context.state==='interrupted')context.resume().catch(()=>{});return context}catch{report('error','engine-context');return null}}
 async function load(){if(buffer||loading||Date.now()<retryAt)return;loading=true;try{const r=await fetch('/audio/racing-engine.wav');if(!r.ok)throw Error();buffer=await context.decodeAudioData(await r.arrayBuffer())}catch{retryAt=Date.now()+10000;report('error','engine-load')}finally{loading=false}}
 function stop(){if(!source)return;try{source.stop();source.disconnect()}catch{}source=null;gain?.gain.setTargetAtTime(0,context.currentTime,.025)}
 function update(r,screen,provided){if(!r)return;settings=r.settings;isScreen=screen;const now=Date.now(),serverNow=now+(window.__raceServerOffset||0),test=now<testUntil,hasPlayers=r.slots.some(Boolean),playing=test||screen&&settings.sound&&settings.engineSound&&hasPlayers&&settings.running&&!settings.paused&&(r.winner===null||r.roundTransition?.immediate)&&serverNow>=r.startsAt;if(!playing){stop();return}if(!unlock(provided)||context.state!=='running'){report('blocked','click-enable-sound');return}if(!buffer){void load();return}if(!source){source=context.createBufferSource();source.buffer=buffer;source.loop=true;source.connect(filter);source.start()}const pace=Math.max(0,...[...(window.Race3D?.motion?.rows?.values()||[])].map(p=>p.pace||0));source.playbackRate.setTargetAtTime(.78+Math.min(.85,pace*.13),context.currentTime,.15);filter.frequency.setTargetAtTime(1600+Math.min(2000,pace*350),context.currentTime,.2);gain.gain.setTargetAtTime((settings.volume??20)/100*(settings.engineVolume??18)/100*.75,context.currentTime,.15);report('playing','original engine effect')}
 function fx(kind){const now=Date.now();if(!context||context.state!=='running'||!isScreen||!settings.sound||!settings.raceFxEnabled||!settings.running||settings.paused||now-lastFx<350)return;lastFx=now;const o=context.createOscillator(),g=context.createGain(),at=context.currentTime,level=(settings.volume??20)/100*(settings.raceFxVolume??25)/100;o.type='sine';o.frequency.setValueAtTime(kind==='pickup'?660:440,at);o.frequency.exponentialRampToValueAtTime(kind==='pickup'?990:220,at+.13);o.connect(g);g.connect(output);g.gain.setValueAtTime(level*.12,at);g.gain.exponentialRampToValueAtTime(.0001,at+.16);o.start();o.stop(at+.17);o.onended=()=>{o.disconnect();g.disconnect()}}
 window.addEventListener('race-visual-event',e=>fx(e.detail.type));document.addEventListener('visibilitychange',()=>{if(!document.hidden&&context&&context.state!=='running'&&context.state!=='closed')context.resume().catch(()=>{})});
 window.RaceSound={unlock,update,test(kind){if(kind!=='engine')return false;unlock();testUntil=Date.now()+5000;return true},get context(){return context},get enginePlaying(){return !!source},get musicPlaying(){return false},get analyser(){return analyser},get buffers(){return {engine:buffer}},get engineRate(){return source?.playbackRate.value||0}};
})();
